svg.script:
/**/
/* Percentage width/height on foreignObject is not reliably honored, so the box
   gets stamped with real pixels. querySelector is used rather than
   getElementById because the shim scopes lookups into the subtree first. */
var fo = document.querySelector("foreignObject");
function sizeToViewport() {
	fo.setAttribute("width", window.innerWidth);
	fo.setAttribute("height", window.innerHeight);
}
sizeToViewport();
window.addEventListener("resize", sizeToViewport);
/**/
